function candidate(){if(!currentVehicle&&!trip&&!busRide){const shop=metropolis.facilities.find(f=>f.kind==='store'&&Math.hypot(player.x-f.counter.x,player.z-f.counter.z)<5);if(shop)return {type:'shop',d:0,text:'E · '+shop.name+' 구매'}}if(busRide)return null;if(currentVehicle)return {type:'exit',v:currentVehicle,d:0,text:'E · 하차 (항공기는 착륙 후 하차)'};if(trip)return null;const options=[];for(const p of pickups)if(p.respawn<=0){const d=Math.hypot(player.x-p.x,player.z-p.z);if(d<3.2&&Math.abs(player.y-(p.floor??0))<3)options.push({type:'pickup',p,d,text:`E · ${p.kind==='weapon'?WEAPONS[p.weapon].name:p.kind==='armor'?'방탄복 +100':p.kind==='ammo'?'탄약 보급':'구급상자'} 획득`})}for(const v of vehicles){const d=Math.hypot(player.x-v.x,player.z-v.z);if(d<8&&v.y<1&&!v.hostile&&!v.destroyed&&!v.occupied&&!v.service)options.push({type:'vehicle',v,d:d*.6,text:`E · ${VEHICLE_TYPES[v.type].name} ${v.traffic?'탈취':'탑승'}`})}for(const s of STATIONS){const d=Math.hypot(player.x-s.x,player.z-s.z-12);if(d<6)options.push({type:'station',s,d,text:`E · ${s.name}역 · ${s.lines.join('·')}호선 이용`})}return options.sort((a,b)=>a.d-b.d)[0]||null}
