function busInteract(){if(busRide){const service=busRide.service;if(!alightBus(service)){message('정류장에 정차하고 문이 열리면 E로 내릴 수 있습니다.');return true}const stop=BUS_STOPS[service.target];Object.assign(player,{x:stop.x,z:stop.z,y:0,vy:0});busRide=null;servedStop=stop.id;message(stop.name+' 정류장 하차',4);return true}const bus=transport.buses.find(b=>b.service.phase==='dwell'&&b.service.doors>.98&&Math.hypot(player.x-BUS_STOPS[b.service.target].x,player.z-BUS_STOPS[b.service.target].z)<8);if(!bus)return false;if(boardBus(bus.service)){busRide=bus;shooting=false;aim=false;reload=0;yaw=busPosition(bus.service).yaw;pitch=0;message('472번 버스 탑승 · 다음 정류장에서 E로 하차',5);return true}return false}
