function updateHostileVehicles(dt){if(elapsed>=nextHostileLaunch){const next=hostileVehicles.find(v=>!v.deployed&&!v.destroyed&&v.enemyPilot.hp>0);if(next){next.deployed=true;next.occupied=true;next.root.visible=true;nextHostileLaunch=elapsed+12;message(VEHICLE_TYPES[next.type].name+' 적 증원 출격',3)}}for(const v of hostileVehicles){if(!v.deployed||v.destroyed||v.enemyPilot.hp<=0)continue;const victim=friendlyTarget({x:v.x,y:v.y+3,z:v.z},650),goal=victim?.point||player,dx=goal.x-v.x,dz=goal.z-v.z,d=Math.hypot(dx,dz),flying=v.type!=='tank';let tx=goal.x,tz=goal.z;if(flying){const radius=v.type==='fighter'?180:85,a=elapsed*(v.type==='fighter'?.24:.13)+hostileVehicles.indexOf(v);tx+=Math.cos(a)*radius;tz+=Math.sin(a)*radius}const desired=Math.atan2(-(tx-v.x),-(tz-v.z)),delta=Math.atan2(Math.sin(desired-v.yaw),Math.cos(desired-v.yaw));if(flying){const speed=v.type==='fighter'?70:19;v.yaw+=clamp(delta,-dt*.7,dt*.7);v.x-=Math.sin(v.yaw)*speed*dt;v.z-=Math.cos(v.yaw)*speed*dt;v.y=Math.max(groundHeight(v.x,v.z)+30,v.type==='fighter'?150:65);v.speed=speed}else if(d<650){const collided=vehicleStep(v,{forward:d>65?1:0,steer:-clamp(delta,-1,1),lift:0,brake:d<65},dt,blocks);if(collided)v.stuck=2;if(v.stuck>0){v.stuck-=dt;vehicleStep(v,{forward:-1,steer:1,lift:0,brake:false},dt,blocks)}}
 if(v.turret)v.turret.rotation.y=Math.atan2(-dx,-dz)-v.yaw;v.attackCooldown-=dt;const origin={x:v.x,y:v.y+3,z:v.z},target=victim?.point||{x:player.x,y:player.y+1.3,z:player.z};if(victim&&d<(flying?360:170)&&d>15&&v.attackCooldown<=0&&!lineBlocked(origin,target,blocks)){v.attackCooldown=v.type==='tank'?4:v.type==='fighter'?2.5:1.8;const miss=world.rand()>.45;tracer(origin,{...target,x:target.x+(miss?7:0)},0xff7f50);if(!miss)hurtFriendly(victim,v.type==='tank'?25:10);if(d<180)sound(v.type==='tank'?'cannon':'enemy',.5)}
}}
