 if(!currentVehicle)return;const v=currentVehicle,oldYaw=v.yaw;vehicleStep(v,{forward:(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0)+mobileMotion.forward,steer:(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+mobileMotion.strafe,lift:(keys.has('Space')?1:0)-(keys.has('KeyQ')?1:0),brake:keys.has('ShiftLeft')},dt,blocks);yaw+=v.yaw-oldYaw;v.root.position.set(v.x,v.y,v.z);v.root.rotation.y=v.yaw;Object.assign(player,{x:v.x,z:v.z,y:v.y});const spec=VEHICLE_TYPES[v.type];const distance=v.type==='plane'?19:v.type==='fighter'?14:9;camera.position.set(v.x+Math.sin(yaw)*distance,v.y+spec.eye+4,v.z+Math.cos(yaw)*distance);camera.rotation.set(pitch,yaw,0);$('vehiclehud').hidden=false;$('vehiclehud').textContent=`${spec.name} · ${Math.round(Math.abs(v.speed)*3.6)} km/h${spec.flying?' · 고도 '+Math.round(v.y)+'m · SPACE 상승 / Q 하강':''}${spec.armed?' · 좌클릭 무장 사격':''}`;
